INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(93542102, 'Morphtronic Celfon', '变形斗士·手机', 'D・モバホン', 'Effect Monster', 'Machine', 'EARTH', 1, 100, 100, '①：这张卡得到表示形式的以下效果。 ●攻击表示：1回合1次，自己主要阶段才能发动。掷1次骰子，把出现的数目数量的卡从自己卡组上面翻开。从那之中选1只4星以下的「变形斗士」怪兽无视召唤条件特殊召唤，剩余回到卡组。 ●守备表示：1回合1次，自己主要阶段才能发动。掷1次骰子，把出现的数目数量的卡从自己卡组上面确认。'),
(91607976, 'Morphtronic Clocken', '变形斗士·电子钟', 'D・クロックン', 'Effect Monster', 'Machine', 'EARTH', 2, 600, 1100, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：这张卡放置的变形斗士指示物每有1个，这张卡的攻击力上升500。 ●守备表示：1回合1次，可以给这张卡放置1个变形斗士指示物。可以把这张卡解放，给与对方基本分这张卡放置的变形斗士指示物数量×1000的数值的伤害。'),
(90659259, 'Morphtronic Converter', '变形斗士·变换装置', 'D・コンバートユニット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只机械族怪兽为对象才能发动。那只怪兽的表示形式的以下效果适用。 ●攻击表示：和作为对象的怪兽卡名不同的1只「变形斗士」怪兽从卡组特殊召唤。那之后，作为对象的怪兽回到持有者卡组最上面。 ●守备表示：作为对象的怪兽变成攻击表示，从手卡把1只4星以下的机械族怪兽特殊召唤。'),
(70423794, 'Morphtronic Cord', '变形斗士·电线', 'D・コード', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「变形斗士」的怪兽才能装备。每次装备怪兽的表示形式改变，场上存在的1张魔法或者陷阱卡破坏。'),
(66331855, 'Morphtronic Datatron', '变形斗士·打火机', 'D・チャッカン', 'Effect Monster', 'Pyro', 'FIRE', 3, 1200, 600, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：可以把自己场上存在的1只怪兽解放给与对方基本分600分伤害。这个效果1回合只能使用1次。 ●守备表示：1回合1次，可以给与对方基本分300分伤害。'),
(37260946, 'Morphtronic Earfon', '变形斗士·耳机', 'D・イヤホン', 'Synchro Monster', 'Machine', 'EARTH', 4, 1200, 1800, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到回合结束时当作调整使用。 ②：以场上1只同调怪兽为对象才能发动。从自己的场上·墓地把这张卡当作装备卡使用给那只怪兽装备。 ③：有这张卡装备的怪兽在同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(7817703, 'Morphtronic Engine', '变形斗士·动力装置', 'D・パワーユニット', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「变形斗士」的3星的怪兽才能装备。装备怪兽的原本攻击力变成2倍。发动后第2次的自己的准备阶段时这张卡破坏，自己受到装备怪兽的原本攻击力数值的伤害。'),
(77229910, 'Morphtronic Forcefield', '变形斗士·防护罩', 'D・バリア', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '把要让自己场上表侧表示存在的名字带有「变形斗士」的怪兽破坏的魔法·陷阱卡的发动无效并破坏。再从自己卡组把1张名字带有「变形斗士」的卡加入手卡。'),
(44413654, 'Morphtronic Impact Return', '变形斗士·冲击归还', 'D・インパクトリターン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以对方场上最多2张魔法·陷阱卡为对象才能发动。从手卡让1只「变形斗士」怪兽回到卡组，作为对象的卡回到持有者卡组。 ②：把墓地的这张卡除外，从自己墓地的怪兽以及除外的自己怪兽之中以1只「变形斗士」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(76865611, 'Morphtronic Lantron', '变形斗士·照明灯', 'D・ライトン', 'Tuner Monster', 'Machine', 'LIGHT', 1, 200, 200, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：只要这张卡在场上表侧表示存在，对方的卡的效果发生的对自己的效果伤害由对方代受。 ●守备表示：这张卡被战斗破坏送去墓地时，这个回合战斗发生的对自己的战斗伤害变成0。'),
(29947751, 'Morphtronic Magnen', '变形斗士·磁铁U', 'D・マグネンU', 'Effect Monster', 'Thunder', 'EARTH', 3, 800, 800, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：对方场上有表侧表示的怪兽存在的场合，这张卡只能选择攻击力最高的怪兽作为攻击对象。 ●守备表示：只要这张卡在场上表侧表示存在，对方不能选择其他怪兽作为攻击对象。'),
(45593005, 'Morphtronic Magnen Bar', '变形斗士·磁铁I', 'D・マグネンI', 'Effect Monster', 'Thunder', 'EARTH', 1, 100, 100, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：自己场上有这张卡以外的怪兽表侧攻击表示2只存在的场合，1回合1次，可以让这张卡的攻击力直到这个回合的结束阶段时上升那些怪兽的攻击力的合计数值。这个效果发动的回合，其他怪兽不能攻击。 ●守备表示：只要这张卡在场上表侧表示存在，自己场上存在的怪兽不能攻击。'),
(56074358, 'Morphtronic Map', '变形斗士·场地', 'D・フィールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：每次场上的怪兽的表示形式变更，给这张卡放置1个变形斗士指示物。 ②：场上的「变形斗士」怪兽的攻击力上升这张卡的变形斗士指示物数量×300。 ③：场上的这张卡被破坏送去墓地时，以自己墓地1只「变形斗士」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(14613029, 'Morphtronic Mix-up', '组合变形斗士', 'ブレンD', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上名字带有「变形斗士」的怪兽有2只以上表侧表示存在的场合，选择对方场上存在的2张卡发动。对方从那之中选择1张，对方选择的1张卡破坏。'),
(28284902, 'Morphtronic Monitron', '变形斗士·监视器', 'D・ゲイザー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '名字带有「变形斗士」的怪兽召唤·反转召唤·特殊召唤成功时，可以把那些怪兽变成表侧守备表示。'),
(55119278, 'Morphtronic Radion', '变形斗士·无线电', 'D・ラジオン', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1000, 900, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：只要这张卡在场上表侧表示存在，自己场上存在的名字带有「变形斗士」的怪兽的攻击力上升800。 ●守备表示：只要这张卡在场上表侧表示存在，自己场上存在的名字带有「变形斗士」的怪兽的守备力上升1000。'),
(57108202, 'Morphtronic Remoten', '变形斗士·遥控器', 'D・リモコン', 'Tuner Monster', 'Machine', 'EARTH', 3, 300, 1200, '①：这张卡得到表示形式的以下效果。 ●攻击表示：1回合1次，以自己墓地1只「变形斗士」怪兽为对象才能发动。那只怪兽除外，等级和那只怪兽相同的1只「变形斗士」怪兽从卡组加入手卡。 ●守备表示：1回合1次，自己主要阶段才能发动。从自己手卡选1只「变形斗士」怪兽送去墓地，从自己墓地选等级和那只怪兽相同的1只其他的「变形斗士」怪兽加入手卡。'),
(90239723, 'Morphtronic Repair Unit', '变形斗士·修复装置', 'D・リペアユニット', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：从手卡把1只「变形斗士」怪兽送去墓地，以自己墓地1只「变形斗士」怪兽为对象才能把这张卡发动。作为对象的怪兽特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽破坏。 ②：装备怪兽不能把表示形式变更。'),
(20686759, 'Morphtronic Rusty Engine', '变形斗士·老式发动机', 'D・レトロエンジン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「变形斗士」的怪兽才能装备。装备怪兽被破坏的场合，双方受到那只怪兽的原本攻击力数值的伤害。'),
(1876841, 'Morphtronic Scannen', '变形斗士·扫描打印机', 'D・スキャナン', 'Tuner Monster', 'Machine', 'EARTH', 6, 1500, 600, '这张卡不能通常召唤。从手卡把1只「变形斗士」怪兽除外的场合可以特殊召唤。 ①：这张卡得到表示形式的以下效果。 ●攻击表示：1回合1次，自己主要阶段才能发动。从卡组把1张「变形斗士」魔法·陷阱卡加入手卡。那之后，选1张手卡回到卡组最上面。 ●守备表示：1回合1次，自己主要阶段才能发动。从自己墓地选1只4星以下的「变形斗士」怪兽加入手卡。那之后，选1张手卡回到卡组最上面。'),
(10591919, 'Morphtronic Scopen', '变形斗士·显微镜', 'D・スコープン', 'Tuner Monster', 'Machine', 'LIGHT', 3, 800, 1400, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：1回合1次，可以从手卡把1只4星的名字带有「变形斗士」的怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段时破坏。 ●守备表示：只要这张卡在场上表侧守备表示存在，这张卡的等级变成4星。'),
(75775867, 'Morphtronic Slingen', '变形斗士·弹弓', 'D・パッチン', 'Effect Monster', 'Machine', 'WIND', 4, 1200, 800, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：1回合1次，可以把「变形斗士·弹弓」以外的1只名字带有「变形斗士」的怪兽解放让场上1张卡破坏。 ●守备表示：这张卡被破坏的场合，可以作为代替把这张卡以外的1只名字带有「变形斗士」的怪兽破坏。'),
(15521027, 'Morphtronic Smartfon', '变形斗士·智能机', 'D・スマホン', 'Tuner Monster', 'Machine', 'EARTH', 1, 100, 100, '这张卡不能通常召唤。从自己墓地把1只「变形斗士」怪兽除外的场合可以特殊召唤。 ①：这张卡得到表示形式的以下效果。 ●攻击表示：1回合1次，自己主要阶段才能发动。掷1次骰子，把出现的数目数量的卡从自己卡组上面翻开。从那之中把1张「变形斗士」卡加入手卡，剩余回到卡组。 ●守备表示：1回合1次，自己主要阶段才能发动。掷1次骰子，把出现的数目数量的卡从自己卡组上面确认，用喜欢的顺序回到卡组上面或下面。'),
(2250266, 'Morphtronic Staplen', '变形斗士·订书机', 'D・ステープラン', 'Effect Monster', 'Machine', 'EARTH', 4, 1400, 1000, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：只要这张卡在场上表侧表示存在，对方不能选择其他怪兽作为攻击对象。这张卡被战斗破坏的场合，把让这张卡破坏的怪兽的攻击力下降300。 ●守备表示：这张卡不会被战斗破坏。这张卡被攻击的场合，那次伤害计算后选择对方场上表侧攻击表示存在的1只怪兽变成守备表示，这张卡的表示形式变成攻击表示。'),
(38082437, 'Morphtronic Telefon', '变形斗士·电话', 'D・テレホン', 'Tuner Monster', 'Machine', 'EARTH', 1, 100, 100, '①：这张卡得到表示形式的以下效果。 ●攻击表示：1回合1次，自己主要阶段才能发动。掷1次骰子。自己回复出现的数目×100基本分。那之后，可以从自己墓地选持有出现的数目以下的等级的1只「变形斗士」怪兽特殊召唤。 ●守备表示：1回合1次，自己主要阶段才能发动。掷1次骰子，把出现的数目数量的卡从自己卡组上面翻开。可以从那之中选1张「变形斗士」卡送去墓地。剩余用喜欢的顺序回到卡组上面或下面。'),
(48868994, 'Morphtronic Vacuumen', '变形斗士·吸尘器', 'D・クリーナン', 'Effect Monster', 'Machine', 'WIND', 1, NULL, NULL, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：1回合1次，可以把这张卡装备的1张装备卡送去墓地，给与对方基本分500分伤害。 ●守备表示：1回合1次，可以把对方场上表侧攻击表示存在的1只怪兽当作装备卡使用只有1只给这张卡装备。'),
(84592800, 'Morphtronic Videon', '变形斗士·摄像机', 'D・ビデオン', 'Effect Monster', 'Machine', 'LIGHT', 4, 1000, 1000, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：这张卡的攻击力上升这张卡装备的装备卡数量×800的数值。 ●守备表示：这张卡的守备力上升这张卡装备的装备卡数量×800的数值。'),
(49833312, 'Morphtronics, Scramble!', '变形斗士·紧急迎击', 'D・スクランブル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方宣言直接攻击时，自己场上没有怪兽存在的场合才能发动。那次攻击无效，从手卡把1只名字带有「变形斗士」的怪兽特殊召唤。'),
(8483333, 'Mosaic Manticore', '嵌合蝎尾狮', 'モザイク・マンティコア', 'Effect Monster', 'Beast', 'EARTH', 8, 2800, 2500, '①：这张卡上级召唤成功的场合，下次的自己回合的准备阶段发动。为这张卡的上级召唤而解放的怪兽从墓地尽可能往自己场上特殊召唤。这个效果特殊召唤的怪兽不能攻击宣言，效果无效化。'),
(57839750, 'Mother Grizzly', '母灰熊', 'グリズリーマザー', 'Effect Monster', 'Beast-Warrior', 'WATER', 4, 1400, 1000, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只攻击力1500以下的水属性怪兽攻击表示特殊召唤。'),
(17021204, 'Mother Spider', '蛛母蜘蛛', 'マザー・スパイダー', 'Effect Monster', 'Insect', 'DARK', 6, 2300, 1200, '自己墓地存在的怪兽只有昆虫族的场合，这张卡可以把对方场上表侧守备表示存在的2只怪兽送去墓地，从手卡特殊召唤。'),
(34034150, 'Mother Spider Splitter', '分裂的蛛母蜘蛛', '分裂するマザー・スパイダー', 'Effect Monster', 'Insect', 'DARK', 5, NULL, 2300, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：把这张卡解放才能发动。从手卡·卡组把最多3只「小蜘蛛」特殊召唤。这个效果特殊召唤的怪兽等级变成5星，作为超量召唤的素材的场合，不是暗属性怪兽的超量召唤不能使用。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。'),
(18837926, 'Motivating Captain', '气冲冲队长', '切れぎみ隊長', 'Effect Monster', 'Warrior', 'EARTH', 1, 400, 1200, '①：这张卡召唤成功时，以自己墓地1只4星以下的怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(77672444, 'Motor Frenzy', '马达暴徒', 'モーターバイオレンス', 'Effect Monster', 'Machine', 'DARK', 6, 2100, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合或者自己场上有这张卡以外的机械族怪兽召唤·特殊召唤的场合才能发动。那些召唤·特殊召唤的怪兽直到对方回合结束时攻击力上升那原本守备力一半数值，不能把表示形式变更。 ②：上级召唤的这张卡被送去墓地的场合才能发动。在自己场上把2只「马达衍生物」（机械族·地·1星·攻/守200）攻击表示特殊召唤。'),
(65515667, 'Motor Kaiser', '马达凯撒', 'モーター・カイザル', 'Effect Monster', 'Machine', 'DARK', 5, 2000, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。进行1只机械族·暗属性怪兽的召唤。 ②：以自己场上1只怪兽为对象才能发动。那只怪兽破坏。那之后，可以在自己场上把1只「马达衍生物」（机械族·地·1星·攻/守200）攻击表示特殊召唤。'),
(78394032, 'Motor Shell', '马达外壳', 'モーターシェル', 'Effect Monster', 'Machine', 'DARK', 4, 1300, 1800, '这个卡名的效果1回合只能使用1次。 ①：这张卡从场上送去墓地的场合才能发动。在自己场上把1只「马达衍生物」（机械族·地·1星·攻/守200）攻击表示特殊召唤。'),
(13959634, 'Moulinglacia the Elemental Lord', '冰灵神 穆岚格雷斯', '氷霊神ムーラングレイス', 'Effect Monster', 'Sea Serpent', 'WATER', 8, 2800, 2200, '这张卡不能通常召唤。自己墓地的水属性怪兽是5只的场合才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合发动。对方手卡随机2张丢弃。 ②：表侧表示的这张卡从场上离开时适用。下次的自己回合的战斗阶段跳过。'),
(269012, 'Mound of the Bound Creator', '神缚之冢', '神縛りの塚', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的10星以上的怪兽不会成为效果的对象，不会被效果破坏。 ②：自己或者对方的10星以上的怪兽战斗破坏怪兽送去墓地的场合发动。破坏的怪兽的控制者受到1000伤害。 ③：场上的这张卡被效果破坏送去墓地时才能发动。从卡组把1只神属性怪兽加入手卡。'),
(70222318, 'Mount Sylvania', '森罗的灵峰', '森羅の霊峰', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '自己的主要阶段时把手卡或者自己场上表侧表示存在的1只植物族怪兽送去墓地才能发动。从卡组选1张名字带有「森罗」的卡在卡组最上面放置。「森罗的灵峰」的这个效果1回合只能使用1次。此外，对方的结束阶段时只有1次，可以把自己卡组最上面的卡翻开。翻开的卡是植物族怪兽的场合，那张卡送去墓地。不是的场合，那张卡回到卡组最上面或者最下面。'),
(50913601, 'Mountain', '山', '山', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部龙族·鸟兽族·雷族的怪兽攻击力·守备力上升200。'),
(4931562, 'Mountain Warrior', '山岳斗士', 'マウンテン・ウォーリアー', 'Normal Monster', 'Beast-Warrior', 'EARTH', 3, 600, 1000, '在处于不利的情况下也可以随意活动的强健战士。'),
(5208118, 'Moving Point Pendulum', NULL, NULL, 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, NULL),
(3395226, 'Mozarta the Melodious Maestra', '幻奏音姬 天才莫扎特', '幻奏の音姫プロディジー・モーツァルト', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2600, 2000, '这张卡的效果发动的回合，自己不能把光属性以外的怪兽特殊召唤。 ①：1回合1次，自己主要阶段才能发动。从手卡把1只天使族·光属性怪兽特殊召唤。'),
(31477025, 'Mr. Volcano', '火山先生', 'ミスターボルケーノ', 'Normal Monster', 'Pyro', 'FIRE', 5, 2100, 1300, '操纵火焰的绅士，平常很和蔼但发起怒来很恐怖。'),
(86767655, 'Ms. Judge', '审判女士', 'Ms.JUDGE', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1800, 600, '「审判女士」的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，对方的卡的效果发动的场合，那次处理进行时进行2次投掷硬币，2次都是表的场合，那个效果无效。'),
(71607202, 'Muckraker From the Underworld', '魔界特派员死亡主播', '魔界特派員デスキャスター', 'Link Monster', 'Fiend', 'DARK', NULL, 1000, NULL, '效果怪兽2只 这个卡名的②的效果1回合只能使用1次。这张卡在连接召唤的回合不能作为连接素材。 ①：自己场上的怪兽被战斗·效果破坏的场合，可以作为代替把自己场上1只恶魔族怪兽解放。 ②：以「魔界特派员 死亡主播」以外的自己墓地1只恶魔族怪兽为对象才能发动。选自己1张手卡丢弃，作为对象的怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是恶魔族怪兽不能特殊召唤。'),
(70307656, 'Mucus Yolk', '咒怨', 'グラッジ', 'Effect Monster', 'Aqua', 'DARK', 3, NULL, 100, '这张卡可以直接攻击对方玩家。这张卡给与对方玩家战斗伤害的场合，下次的自己的准备阶段时这张卡的攻击力上升1000。'),
(71002019, 'Mudan the Rikka Fairy', '六花精牡丹', '六花精ボタン', 'Effect Monster', 'Plant', 'WATER', 6, 1000, 2400, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只植物族怪兽解放才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤或者用植物族怪兽的效果特殊召唤成功的场合才能发动。从卡组把1张「六花」魔法·陷阱卡加入手卡。'),
(84040113, 'Muddy Mudragon', '泥泥龙', 'ドロドロゴン', 'Synchro Monster', 'Dragon', 'DARK', 6, 500, 2200, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：融合怪兽融合召唤的场合，场上·墓地的这张卡可以作为那只融合怪兽有卡名记述的1只融合素材怪兽代用（其他的融合素材不能代用）。 ②：这张卡是已同调召唤的场合，自己主要阶段才能发动。包含这张卡的自己场上的怪兽作为融合素材，把1只融合怪兽融合召唤。'),
(82108372, 'Mudora', '姆多拉', 'ムドラ', 'Effect Monster', 'Fairy', 'EARTH', 4, 1500, 1800, '自己墓地里每存在1只天使族怪兽，这张卡的攻击力上升200点。'),
(99937011, 'Mudora the Sword Oracle', '剑神官 姆多拉', '剣神官ムドラ', 'Effect Monster', 'Fairy', 'EARTH', 4, 1500, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1只其他的天使族·地属性怪兽才能发动。这张卡从手卡特殊召唤。那之后，可以从卡组选1张「守墓的陷阱」在自己的魔法与陷阱区域表侧表示放置。 ②：自己·对方回合，把场上·墓地的这张卡除外，以自己·对方的墓地的卡合计最多5张为对象才能发动。那些卡回到卡组。自己的场上以及墓地没有「现世与冥界的逆转」存在的场合，这个效果的对象变成最多3张。'),
(54757758, 'Mudragon of the Swamp', '沼地泥龙', '沼地のドロゴン', 'Fusion Monster', 'Wyrm', 'WATER', 4, 1900, 1600, '相同属性而种族不同的怪兽×2 ①：只要这张卡在怪兽区域存在，对方不能把这张卡以及持有和这张卡相同属性的场上的怪兽作为效果的对象。 ②：1回合1次，宣言1个属性才能发动。这张卡直到回合结束时变成宣言的属性。这个效果在对方回合也能发动。'),
(46657337, 'Muka Muka', '姆卡姆卡', 'ムカムカ', 'Effect Monster', 'Rock', 'EARTH', 2, 600, 300, '只要这张卡表侧表示在场上存在，控制者手上每有1张卡，这张卡的攻击力·守备力上升300。'),
(80863132, 'Muko', '无效', '無効', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '抽卡的效果发动时发动。那张卡的效果所抽的卡双方确认，并全部丢弃去墓地。'),
(42141493, 'Mulcharmy Fuwalos', '多多迷宝・软绵雀精', 'マルチャミー・フワロス', 'Effect Monster', 'Winged Beast', 'WIND', 4, 100, 600, '这张卡的效果发动的回合，自己只能有1次把这张卡以外的「欢聚友伴」怪兽的效果发动。 ①：自己·对方回合，自己场上没有卡存在的场合，把这张卡从手卡丢弃才能发动。这个回合中，以下效果适用。 ●每次对方从卡组·额外卡组把怪兽特殊召唤，自己抽1张。 ●结束阶段，自己手卡比对方场上的卡数量＋6张要多的场合，那个相差数量的自己手卡随机回到卡组。'),
(87126721, 'Mulcharmy Meowls', '多多迷宝・喵噜猫咪', 'マルチャミー・ニャルス', 'Effect Monster', 'Beast', 'EARTH', 4, 100, 600, '这张卡的效果发动的回合，自己只能有1次把这张卡以外的「欢聚友伴」怪兽的效果发动。 ①：自己·对方回合，自己场上没有卡存在的场合，把这张卡从手卡丢弃才能发动。这个回合中，以下效果适用。 ●每次对方把墓地·除外状态的怪兽特殊召唤，自己抽1张。 ●结束阶段，自己手卡比对方场上的卡数量＋6张要多的场合，那个相差数量的自己手卡随机回到卡组。'),
(84192580, 'Mulcharmy Purulia', '多多迷宝・噗噜海月', 'マルチャミー・プルリア', 'Effect Monster', 'Aqua', 'WATER', 4, 100, 600, '这张卡的效果发动的回合，自己只能有1次把这张卡以外的「欢聚友伴」怪兽的效果发动。 ①：自己·对方回合，自己场上没有卡存在的场合，把这张卡从手卡丢弃才能发动。这个回合中，以下效果适用。 ●每次对方从手卡把怪兽召唤·特殊召唤，自己抽1张。 ●结束阶段，自己手卡比对方场上的卡数量＋6张要多的场合，那个相差数量的自己手卡随机回到卡组。'),
(35514097, 'Multi Token', '罗德不列颠号', 'ロードブリティッシュ', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(885016, 'Multi-Universe', '多元宇宙', '多元宇宙', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '自己的场地区域没有表侧表示卡存在的场合才能把这张卡发动。这个卡名的①的效果1回合只能使用1次。 ①：以自己或对方的墓地·除外状态的1张场地魔法卡为对象才能发动。这张卡破坏，作为对象的卡在自己的场地区域表侧表示放置。 ②：场地区域的卡被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(14057297, 'Multiple Destruction', '同归于尽', '死なばもろとも', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：双方手卡各自是3张以上的场合才能发动。双方玩家各自让手卡全部用喜欢的顺序回到卡组下面，自己失去这个效果让双方回到卡组的卡数量×300基本分。那之后，双方玩家各自从卡组抽5张。'),
(71628381, 'Multiple Piece Golem', '多块石人', 'マルチ・ピース・ゴーレム', 'Fusion Monster', 'Rock', 'EARTH', 7, 2600, 1300, '「大块石人」＋「中块石人」 这张卡进行战斗的战斗阶段结束时可以让这张卡回到额外卡组。并且，若回到额外卡组的这张卡的融合召唤使用过的1组融合素材怪兽在自己墓地齐集，可以再把这1组在自己场上特殊召唤。'),
(22493811, 'Multiplication of Ants', '蚂蚁的增殖', 'アリの増殖', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '祭掉自己场上1只昆虫族怪兽发动。在自己场上特殊召唤2只「兵队衍生物」（地·4星·昆虫族·攻500·守1200）。（不能用作上级召唤的祭品）'),
(40703222, 'Multiply', '增殖', '増殖', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的1只「栗子球」解放才能发动。在自己场上把「栗子球衍生物」（恶魔族·暗·1星·攻300/守200）尽可能守备表示特殊召唤。这衍生物不能为上级召唤而解放。'),
(92385016, 'Munin the Runick Wings', '神碑之翼 雾尼', '神碑の翼ムニン', 'Fusion Monster', 'Fairy', 'LIGHT', 3, NULL, 2000, '「神碑」怪兽×2 ①：这张卡从额外卡组的特殊召唤成功的场合，丢弃1张手卡才能发动。从卡组把1张「神碑」永续魔法卡加入手卡。 ②：以自己场上的「神碑」卡或者盖放的卡为对象的魔法·陷阱·怪兽的效果由对方发动时，把场上的这张卡除外才能发动。那个发动无效并破坏。 ③：自己·对方的结束阶段发动。自己回复1000基本分。'),
(60398723, 'Murmur of the Forest', '森林的沙沙作响', '森のざわめき', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方场上表侧表示存在的1只怪兽变成里侧守备表示。那之后，可以让场上存在的场地魔法卡回到持有者手卡。'),
(41458579, 'Musakani Magatama', '六尺琼勾玉', '六尺瓊勾玉', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上有「六武众」怪兽存在，要让卡破坏的怪兽的效果·魔法·陷阱卡由对方发动时才能发动。那个发动无效并破坏。'),
(4848423, 'Muscle Medic', '卫生兵 肌肉大汉', '衛生兵マッスラー', 'Effect Monster', 'Warrior', 'WATER', 4, 2200, 100, '①：这张卡的战斗让自己或者对方受到战斗伤害的场合，作为代替让基本分回复那个数值。'),
(69992868, 'Muse-A', '缪斯天使', 'ミューズの天使', 'Normal Monster', 'Fairy', 'LIGHT', 3, 850, 900, '艺术家的天使。尤其琴技无人能出其右。'),
(14181608, 'Mushroom Man', '蘑菇人', 'きのこマン', 'Normal Monster', 'Plant', 'EARTH', 2, 800, 600, '在潮湿的地方发挥力量！从蘑菇帽中吐丝攻击。'),
(93900406, 'Mushroom Man #2', '蘑菇怪人', 'マタンゴ', 'Effect Monster', 'Warrior', 'EARTH', 3, 1250, 800, '每次的自己准备阶段受到300分的伤害。可以在自己的结束阶段支付500分，把这张卡的控制权转移给对方。'),
(96637156, 'Musical Sumo Dice Games', '席取-六双丸', '席取－六双丸', 'XYZ Monster', 'Machine', 'FIRE', 6, 600, 3000, '6星怪兽×2 ①：对方战斗阶段开始时发动。掷1次骰子。双方的主要怪兽区域从这张卡来看以顺时针转法从下1区算起作为1～6，主要怪兽区域的这张卡向出现数目字的区域移动。所去移动区有怪兽存在的场合，那只在这下面重叠作为超量素材（持有超量素材的怪兽的场合那些也全部重叠）。这超量素材超过6个时，自己决斗胜利。不能移动的场合或者不能把在所去移动区的怪兽作为超量素材的场合，这张卡送去墓地。'),
(56907389, 'Musician King', '音乐家之帝王', '音楽家の帝王', 'Fusion Monster', 'Spellcaster', 'LIGHT', 5, 1750, 1500, '「黑森林的魔女」＋「高等女祭司」'),
(68191243, 'Mustering of the Dark Scorpions', '黑蝎团召集', '黒蠍団召集', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '当自己场上存在表侧表示的「首领 扎鲁格」时这张卡才能发动。可以从手卡里将名称中含有「黑蝎」字样的怪兽全部特殊召唤上场。（同名怪兽只能特殊召唤1只）'),
(9837195, 'Musto, Oracle of Gusto', '薰风的神官 穆斯托', 'ガスタの神官 ムスト', 'Effect Monster', 'Psychic', 'WIND', 4, 1800, 900, '可以选择自己墓地存在的1只名字带有「薰风」的怪兽回到卡组，选择场上表侧表示存在的1只怪兽把那个效果直到结束阶段时无效。这个效果1回合只能发动1次。'),
(88654892, 'Mutamorphosis', '突然回归', '突然回帰', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只融合·同调怪兽解放才能发动。把持有和解放的怪兽的原本等级相同等级的1只怪兽从卡组特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到手卡。'),
(11508758, 'Mutant Mindmaster', '变异先导者', 'ミュータント・ハイブレイン', 'Effect Monster', 'Spellcaster', 'DARK', 6, NULL, 2500, '①：对方场上有怪兽2只以上存在的场合，这张卡的攻击宣言时，以对方场上1只表侧攻击表示怪兽为对象才能发动。那1只对方的表侧攻击表示怪兽的控制权直到战斗阶段结束时得到。作为对象的怪兽在这个回合不能直接攻击，在可以攻击的场合，选1只对方怪兽作为攻击对象进行伤害计算。'),
(71593652, 'Mutiny in the Sky', '天国之乱', NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己墓地的恶魔族·天使族怪兽作为融合素材回到卡组，把1只恶魔族·天使族融合怪兽融合召唤。 这张卡在自己墓地存在的场合：可以从自己的手卡·场上（表侧）把1只恶魔族·天使族怪兽送去墓地；这张卡加入手卡。 「天国之乱」的每个效果1回合各能使用1次。'),
(75364199, 'Mutually Affured Destruction', '相视相杀', '相視相殺', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合，双方玩家把手卡持续公开。这个效果把手卡持续公开期间，双方手卡有同名卡存在的场合，双方不能作那卡以及那些同名卡的效果的发动。'),
(26563200, 'Muzurhythm the String Djinn', '弦魔人 跃跃节奏', '弦魔人ムズムズリズム', 'XYZ Monster', 'Fiend', 'WIND', 3, 1500, 1000, '3星怪兽×2 自己场上的名字带有「魔人」的超量怪兽向对方怪兽攻击的伤害步骤时，把这张卡1个超量素材取除才能发动。那只攻击怪兽的攻击力直到结束阶段时变成2倍。「弦魔人 跃跃节奏」的效果1回合只能使用1次。'),
(69279219, 'My Body as a Shield', '我身作盾', '我が身を盾に', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '支付1500基本分发动。对方发动的持有「把场上的怪兽破坏的效果」的卡的发动无效并破坏。'),
(56700100, 'My Friend Purrely', '我的朋友・皮尔莉', 'ピュアリィ・マイフレンド', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：支付500基本分才能发动。从卡组把「我的纯爱妖精朋友」以外的3张「纯爱妖精」卡给对方观看，对方从那之中随机选1张。那1张加入自己手卡，剩余回到卡组。 ②：自己场上的表侧表示的「纯爱妖精」超量怪兽因对方从场上离开的场合才能发动（伤害步骤也能发动）。从自己墓地选最多3张「纯爱妖精」速攻魔法卡加入手卡（同名卡最多1张）。'),
(13735899, 'Mysterion the Dragon Crown', '秘仪之龙冠', 'ミュステリオンの竜冠', 'Fusion Monster', 'Spellcaster', 'LIGHT', 8, 3000, 1500, '魔法师族怪兽＋龙族怪兽 这张卡不能作为融合素材。这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力下降自己的除外状态的卡数量×100。 ②：怪兽发动的效果让那只怪兽或者原本种族和那只怪兽相同的怪兽特殊召唤的场合，以那之内的1只为对象才能发动。作为对象的怪兽以及原本种族和那只怪兽相同的场上的怪兽全部除外。'),
(1347977, 'Mysterious Guard', '神圣守卫者', '聖なる守り手', 'Flip Effect Monster', 'Spellcaster', 'EARTH', 3, 800, 1200, '①：这张卡反转的场合，从以下效果选择1个发动。 ●以场上1只表侧表示怪兽为对象发动。那只表侧表示怪兽回到持有者卡组最上面。 ●自己场上有战士族怪兽存在的场合，以场上2只表侧表示怪兽为对象发动。那1只表侧表示怪兽回到持有者卡组最上面。那之后，自己场上有战士族怪兽存在的场合，另1只表侧表示怪兽回到持有者手卡。'),
(54098121, 'Mysterious Puppeteer', '谜之傀儡师', '謎の傀儡師', 'Effect Monster', 'Warrior', 'EARTH', 4, 1000, 1500, '怪兽召唤·反转召唤成功时，自己回复500基本分。'),
(53291093, 'Mysterious Triangle', '三角区', 'トライアングル・エリア', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把场上存在的1只有A指示物放置的怪兽破坏。并且可以再从自己卡组把1只名字带有「外星」的4星怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段时破坏。'),
(62793020, 'Mystery Hand', '谜之手', 'なぞの手', 'Normal Monster', 'Fiend', 'DARK', 2, 500, 500, '弄歪空间，从次元的狭间中伸出手腕进行攻击。'),
(18108166, 'Mystery Shell Dragon', '幻壳龙', '幻殻竜', 'Normal Monster', 'Wyrm', 'DARK', 4, 2000, NULL, '从别的次元突然飞来的神秘生命体。同时具备了高攻击力和奇袭能力。它的攻击使对象物的神经麻痹，并引起强烈的幻觉症状。'),
(25774450, 'Mystic Box', '死之魔术箱', '死のマジック・ボックス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己以及对方场上的怪兽各1只为对象才能发动。那只对方怪兽破坏。那之后，那只自己怪兽的控制权移给对方。'),
(47060154, 'Mystic Clown', '狂战士', 'バーサーカー', 'Normal Monster', 'Fiend', 'DARK', 4, 1500, 1000, '用狂暴的力量攻击，一旦暴走无人能挡。'),
(68516705, 'Mystic Horseman', '人马兽', 'ケンタウロス', 'Normal Monster', 'Beast', 'EARTH', 4, 1300, 1550, '人和马合为一体的怪物。跑得很快，谁都追不上。'),
(98049915, 'Mystic Lamp', '魔法灯', '魔法のランプ', 'Effect Monster', 'Spellcaster', 'DARK', 1, 400, 300, '这张卡可以直接攻击对方玩家。'),
(51912531, 'Mystic Macrocarpa Seed', '幻妖种 密多罗', '幻妖種ミトラ', 'Tuner Monster', 'Plant', 'EARTH', 3, 500, 1000, '把这张卡作为同调素材的场合，不是地属性怪兽的同调召唤不能使用。自己的主要阶段时，选择场上1只地属性怪兽才能发动。选择的怪兽的等级下降1星。「幻妖种 密多罗」的效果1回合可以使用最多2次。'),
(76375976, 'Mystic Mine', '魔钟洞', '魔鍾洞', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：对方场上的怪兽数量比自己场上的怪兽多的场合，对方不能把怪兽的效果发动，也不能攻击宣言。 ②：自己场上的怪兽数量比对方场上的怪兽多的场合，自己不能把怪兽的效果发动，也不能攻击宣言。 ③：自己·对方的结束阶段，双方场上的怪兽数量相同的场合发动。这张卡破坏。'),
(14198496, 'Mystic Piper', '神秘吹笛人', 'ミスティック・パイパー', 'Effect Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '把这张卡解放发动。从自己卡组抽1张卡。这个效果抽到的卡给双方确认，1星怪兽的场合，自己再抽1张卡。「神秘之吹笛人」的效果1回合只能使用1次。'),
(18161786, 'Mystic Plasma Zone', '暗黑地带', 'ダークゾーン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部的暗属性的怪兽攻击力上升500，守备力下降400。'),
(97534104, 'Mystic Potato', '杀人马铃薯', 'キラー・ポテト', 'Effect Monster', 'Plant', 'DARK', 4, 1400, 1100, '①：场上的这张卡被效果破坏送去墓地的场合才能发动。除「杀人马铃薯」外的1只攻击力1500以下的暗属性怪兽从卡组攻击表示特殊召唤。'),
(49251811, 'Mystic Probe', '魔法探查石板', '魔法探査の石版', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '永续魔法卡发动时才能发动。直到回合结束时场上的全部永续魔法卡的效果无效。'),
(47507260, 'Mystic Swordsman LV2', '谜之剑士 LV2', 'ミスティック・ソードマン LV２', 'Effect Monster', 'Warrior', 'EARTH', 2, 900, NULL, '攻击里侧守备表示怪兽的场合，不进行伤害计算，那只怪兽以里侧守备表示的状态直接破坏。这张卡战斗破坏怪兽的回合的结束阶段，可以把这张卡送去墓地，从手卡·卡组特殊召唤1只「谜之剑士 LV4」'),
(74591968, 'Mystic Swordsman LV4', '谜之剑士 LV4', 'ミスティック・ソードマン LV４', 'Effect Monster', 'Warrior', 'EARTH', 4, 1900, 1600, '当这张卡在通常召唤的场合时，必须里侧守备表示出场。攻击里侧守备表示怪兽的场合，不进行战斗伤害，那只怪兽以里侧守备表示的状态直接破坏。这张卡战斗破坏怪兽的回合的结束阶段，可以把这张卡送去墓地，从手卡·卡组特殊召唤1只「谜之剑士 LV6」'),
(60482781, 'Mystic Swordsman LV6', '谜之剑士 LV6', 'ミスティック・ソードマン LV６', 'Effect Monster', 'Warrior', 'EARTH', 6, 2300, 1700, '这张卡通常召唤的场合，必须以里侧守备表示的形式出场。攻击里侧守备表示的怪兽时，不进行伤害计算，那只怪兽以里侧守备表示的状态直接破坏。此效果破坏的怪兽可以不送去墓地，放到对方卡组的最上面。'),
(83011278, 'Mystic Tomato', '杀手番茄', 'キラー・トマト', 'Effect Monster', 'Plant', 'DARK', 4, 1400, 1100, NULL),
(89194033, 'Mystical Beast of Serket', '圣兽 塞尔凯特', '聖獣セルケト', 'Effect Monster', 'Fairy', 'EARTH', 6, 2500, 2000, '①：自己场上没有「王家的神殿」存在的场合这张卡破坏。 ②：这张卡战斗破坏的怪兽不去墓地而除外。 ③：这张卡战斗破坏怪兽的场合发动。这张卡的攻击力上升500。'),
(63515678, 'Mystical Capture Chain', '神圣之锁', '聖なる鎖', 'Normal Monster', 'Fairy', 'LIGHT', 2, 700, 700, '据说可以用神圣的力量封锁行动的锁链。'),
(48356796, 'Mystical Cards of Light', '闪光之宝札', '閃光の宝札', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，自己的魔法与陷阱卡区域1处变成不能使用。这张卡以外的「闪光之宝札」在自己场上表侧表示存在的场合，自己的抽卡阶段时的通常抽卡可以抽2张卡。'),
(15025844, 'Mystical Elf', '圣精灵', 'ホーリー・エルフ', 'Normal Monster', 'Spellcaster', 'LIGHT', 4, 800, 2000, '虽然是纤弱的精灵，但以神圣力量护身有很强的守备。'),
(15613529, 'Mystical Elf - White Lightning', '圣精灵－圣爆裂疾风弹', 'ホーリー・エルフ－ホーリー・バースト・ストリーム', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 800, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有5星以上的通常怪兽存在，对方场上的怪兽把效果发动时才能发动。这张卡从手卡特殊召唤，那个效果无效。 ②：对方战斗阶段，以自己或者对方的墓地1只通常怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。这个回合，只要那只怪兽在自己场上存在，可以攻击的对方怪兽必须向那只怪兽作出攻击。'),
(85239662, 'Mystical Fairy Elfuria', '神秘之妖精 艾尔菲莉娅', '神秘の妖精 エルフィリア', 'Effect Monster', 'Spellcaster', 'WIND', 3, 1500, 900, '1回合1次，把手卡1只风属性怪兽给对方观看才能发动。直到下次的对方的结束阶段时，双方玩家不能用持有给人观看的怪兽的等级以外的等级的怪兽为素材作超量召唤。'),
(98745000, 'Mystical Knight of Jackal', '胡狼圣战士', 'ジャッカルの聖戦士', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 7, 2700, 1200, '这张卡战斗破坏对方场上1只怪兽并将送其进墓地时，可以把那张卡放回对方卡组最上面。'),
(36607978, 'Mystical Moon', '魔性之月', '魔性の月', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '兽战士族怪兽才能装备。装备怪兽的攻击力·守备力上升300。'),
(35563539, 'Mystical Refpanel', '精灵之镜', '精霊の鏡', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '玩家1人为对象的魔法的效果移给其他玩家。'),
(32751480, 'Mystical Sand', '砂之魔女', '砂の魔女', 'Fusion Monster', 'Rock', 'EARTH', 6, 2100, 1700, '「岩石巨兵」＋「古代精灵」'),
(30451366, 'Mystical Sheep #1', '幻想绵羊', 'イリュージョン・シープ', 'Effect Monster', 'Beast', 'EARTH', 3, 1150, 900, '这张卡可以作为1只融合素材怪兽的代替。那个时候，其他的融合素材怪兽必须是正规品。'),
(83464209, 'Mystical Sheep #2', '催眠羊', 'スリーピィ', 'Normal Monster', 'Beast', 'EARTH', 3, 800, 1000, '尾巴很长的绵羊，用尾巴使出催眠术，让敌人入睡。'),
(39552864, 'Mystical Shine Ball', '神圣球体', '神聖なる球体', 'Normal Monster', 'Fairy', 'LIGHT', 2, 500, 500, '被神圣光辉包住的天使灵魂。看见其美丽姿态者，据说能够实现愿望。'),
(5318639, 'Mystical Space Typhoon', '气旋', 'サイクロン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(63516460, 'Mystical Wind Typhoon', '一阵之风', '一陣の風', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '连锁3以后才能发动。把场上的1张魔法或者陷阱卡破坏。同1组连锁上有复数次同名卡的效果发动的场合，这张卡不能发动。'),
(80161395, 'Mystik Wok', '神秘的中华锅', '神秘の中華なべ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己场上1只怪兽作为祭品。选择祭品怪兽的攻击力或守备力，自己基本分回复那个数值。'),
(81263643, 'Mystrick Hulder', '幻妖 胡尔德拉', '幻妖フルドラ', 'Effect Monster', 'Spellcaster', 'DARK', 5, 1500, 2400, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，丢弃1张手卡才能发动。丢弃的卡种类的以下效果适用。 ●怪兽：从自己墓地选1张陷阱卡加入手卡。 ●魔法：从自己墓地选1只怪兽加入手卡。 ●陷阱：从自己墓地选1张魔法卡加入手卡。'),
(300102002, 'Mythic Depths', NULL, NULL, 'Skill Card', 'Mako', NULL, NULL, NULL, NULL, NULL),
(50457953, 'Mythic Tree Dragon', '幻木龙', '幻木龍', 'Effect Monster', 'Dragon', 'EARTH', 4, 100, 1400, '1回合1次，选择自己场上1只龙族·水属性怪兽才能发动。这张卡的等级变成和选择的怪兽的等级相同。'),
(92841002, 'Mythic Water Dragon', '幻水龙', '幻水龍', 'Effect Monster', 'Dragon', 'WATER', 8, 1000, 2000, '自己场上有地属性怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法的「幻水龙」的特殊召唤1回合只能有1次。'),
(80959027, 'Mythical Beast Bashilisk', '魔导兽 巴西利斯克', '魔導獣 バジリスク', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 4, 1800, 500, '这个卡名的②的怪兽效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。 ②：把自己场上3个魔力指示物取除才能发动。从自己的灵摆区域的卡以及自己的额外卡组的表侧表示的灵摆怪兽之中选1张「魔导兽」卡回到持有者手卡。'),
(55424270, 'Mythical Beast Cerberus', '魔导兽 刻耳柏洛斯', '魔導獣 ケルベロス', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1400, 1400, '①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。 ②：这张卡的攻击力上升这张卡的魔力指示物数量×500。 ③：这张卡进行战斗的战斗阶段结束时这张卡的魔力指示物全部取除。'),
(28570310, 'Mythical Beast Garuda', '魔导兽 迦楼罗', '魔導獣 ガルーダ', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 4, 1200, 1600, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：对方对怪兽的召唤·特殊召唤成功时，把自己场上3个魔力指示物取除才能发动。这张卡从手卡特殊召唤。那之后，对方召唤·特殊召唤的那些怪兽回到持有者手卡。 ②：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。'),
(91182675, 'Mythical Beast Jackal', '魔导兽 胡狼', '魔導獣 ジャッカル', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 1, NULL, 1400, '①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。 ②：把自己场上3个魔力指示物取除，把这张卡解放才能发动。从卡组把「魔导兽 胡狼」以外的1只「魔导兽」效果怪兽特殊召唤。'),
(27354732, 'Mythical Beast Jackal King', '魔导兽 胡狼王', '魔導獣 キングジャッカル', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 6, 2400, 1400, '①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置2个魔力指示物。 ②：1回合1次，对方怪兽的效果发动时，把自己场上2个魔力指示物取除才能发动。那个发动无效并破坏。'),
(53842431, 'Mythical Beast Master Cerberus', '魔导兽 刻耳柏洛斯尊主', '魔導獣 マスターケルベロス', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 8, 2800, 2800, '①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置2个魔力指示物。 ②：自己场上有魔力指示物4个以上存在的场合，这张卡不会被效果破坏。 ③：1回合1次，把自己场上4个魔力指示物取除，以对方场上1只怪兽为对象才能发动。那只怪兽除外。这张卡的攻击力直到对方回合结束时上升除外的那只怪兽的原本攻击力数值。'),
(54965929, 'Mythical Beast Medusa', '魔导兽 美杜莎', '魔導獣 メデューサ', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 4, 1500, 1500, '①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。 ②：1回合1次，自己·对方的战斗阶段，把自己场上2个魔力指示物取除，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时变成一半。'),
(24429467, 'Mythical Bestiamorph', '魔导变换', '魔導変換', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，每次对方怪兽的效果发动，给这张卡放置1个魔力指示物。 ②：把有魔力指示物6个以上放置的这张卡送去墓地才能发动。从卡组把1张魔法卡加入手卡。'),
(38325384, 'Mythical Bestiary', '魔导加速', '魔導加速', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己卡组上面把2张卡送去墓地，以场上1张可以放置魔力指示物的卡为对象才能发动。给那张卡放置最多2个魔力指示物。 ②：这张卡被对方的效果破坏的场合才能发动。可以放置魔力指示物的1只怪兽从卡组特殊召唤，给那只怪兽放置最多2个魔力指示物。'),
(94599451, 'Mythical Institution', '魔导研究所', '魔導研究所', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：每次自己场上的表侧表示的「魔导兽」灵摆怪兽卡被战斗·效果破坏给这张卡放置2个魔力指示物。 ②：1回合1次，把自己场上的魔力指示物任意数量取除才能发动。从卡组的怪兽以及自己的额外卡组的表侧表示的灵摆怪兽之中选持有和取除数量相同等级的1只可以放置魔力指示物的怪兽加入手卡。 ③：场上的这张卡被效果破坏的场合，可以作为代替把这张卡1个魔力指示物取除。'),
(7574904, 'Myutant Arsenal', '秘异三变武装者', 'ミュートリアル・アームズ', 'Effect Monster', 'Machine', 'FIRE', 8, 3000, 1000, '这张卡不用「秘异三变」卡的效果不能特殊召唤。这个卡名的②③的效果1回合各能使用1次。 ①：这张卡不会成为对方的陷阱卡的效果的对象。 ②：对方把怪兽的效果发动时，从自己的手卡·场上把1张卡除外，以场上1只怪兽为对象才能发动。那只怪兽除外。 ③：这张卡被对方破坏的场合，以除外的1张自己的「秘异三变」魔法卡为对象才能发动。那张卡加入手卡。'),
(34695290, 'Myutant Beast', '秘异三变猛兽', 'ミュートリアル・ビースト', 'Effect Monster', 'Beast', 'EARTH', 8, 2400, 2400, '这张卡不用「秘异三变」卡的效果不能特殊召唤。这个卡名的②③的效果1回合各能使用1次。 ①：这张卡不会成为对方怪兽的效果的对象。 ②：对方把魔法卡的效果发动时，从自己的手卡·场上把1张卡除外才能发动。那个发动无效并除外。 ③：这张卡被对方破坏的场合，以除外的1张自己的「秘异三变」陷阱卡为对象才能发动。那张卡加入手卡。'),
(79072916, 'Myutant Blast', '秘异三变体反射作用', 'ミュートリア反射作用', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的8星以上的「秘异三变」怪兽才能装备。这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽向特殊召唤的对方怪兽攻击的伤害步骤开始时才能发动。那只对方怪兽除外。 ②：把装备的这张卡除外才能发动。这张卡装备过的怪兽送去墓地，原本属性和那只怪兽不同的1只8星「秘异三变」怪兽从手卡·卡组特殊召唤。'),
(5466615, 'Myutant Clash', '秘异三变体连锁应动', 'ミュートリア連鎖応動', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：这张卡的发动时，可以以对方场上1只效果怪兽为对象。那个场合，从自己墓地选1只「秘异三变」怪兽除外，作为对象的怪兽的效果直到回合结束时无效。 ②：自己的8星以上的「秘异三变」怪兽战斗破坏对方怪兽时才能发动。自己从卡组抽1张。'),
(31855260, 'Myutant Cry', '秘异三变联体的产声', 'ミュートリアスの産声', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段才能发动。从自己的场上·墓地的怪兽以及除外的自己怪兽之中让「秘异三变」融合怪兽卡决定的融合素材怪兽回到持有者卡组，把那1只融合怪兽从额外卡组融合召唤。'),
(34572613, 'Myutant Evolution Lab', '秘异三变体进化研究所', 'ミュートリア進化研究所', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从手卡以及除外的自己怪兽之中选1只4星以下的「秘异三变」怪兽特殊召唤。 ②：自己场上的「秘异三变」怪兽的攻击力上升除外的自己的「秘异三变」卡的卡名种类×100。 ③：1回合1次，自己主要阶段才能发动。从手卡让1只「秘异三变」怪兽回到卡组最下面，自己从卡组抽1张。'),
(60967717, 'Myutant Expansion', '秘异三变体超个体系', 'ミュートリア超個体系', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只4星以下的「秘异三变」怪兽加入手卡或特殊召唤。 ②：自己场上的8星以上的「秘异三变」怪兽被效果破坏的场合，可以作为代替把场上的这张卡除外。'),
(42577802, 'Myutant Fusion', '融合秘异三变联体', 'フュージョン・ミュートリアス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上把「秘异三变」融合怪兽卡决定的融合素材怪兽除外，把那1只融合怪兽从额外卡组融合召唤。这个回合对方是已把卡的效果发动的场合，自己的卡组·墓地的怪兽也各能有最多1只作为融合素材。'),
(43709490, 'Myutant GB-88', '被检体 秘异三变体GB-88', '被検体ミュートリアGB－８８', 'Effect Monster', 'Psychic', 'WATER', 4, 500, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的场地区域有「秘异三变体进化研究所」存在的场合，对方主要阶段才能发动。这张卡从手卡特殊召唤。 ②：对方回合，这张卡特殊召唤成功的场合，把这张卡解放，把1张手卡或者自己场上的表侧表示的卡除外才能发动。从自己墓地的怪兽以及除外的自己怪兽之中选1只8星「秘异三变」怪兽特殊召唤。'),
(62201847, 'Myutant M-05', '被检体 秘异三变体M-05', '被検体ミュートリアM－０５', 'Effect Monster', 'Psychic', 'WATER', 2, NULL, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「被检体 秘异三变体M-05」以外的1只「秘异三变」怪兽加入手卡。 ②：把这张卡解放，把1张手卡或者自己场上的表侧表示的卡除外才能发动。除外的卡种类的1只以下怪兽从手卡·卡组特殊召唤。 ●怪兽：「秘异三变猛兽」 ●魔法：「秘异三变秘法家」 ●陷阱：「秘异三变武装者」'),
(61089209, 'Myutant Mist', '秘异三变秘法家', 'ミュートリアル・ミスト', 'Effect Monster', 'Spellcaster', 'WIND', 8, 2700, 2900, '这张卡不用「秘异三变」卡的效果不能特殊召唤。这个卡名的②③的效果1回合各能使用1次。 ①：这张卡不会成为对方的魔法卡的效果的对象。 ②：对方把陷阱卡的效果发动时，从自己的手卡·场上把1张卡除外才能发动。自己从卡组抽2张。 ③：这张卡被对方破坏的场合，以除外的1只自己的「秘异三变」怪兽为对象才能发动。那只怪兽加入手卡。'),
(26561172, 'Myutant Mutant', '变异体 秘异三变体', '変異体ミュートリア', 'Effect Monster', 'Psychic', 'WATER', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「秘异三变」卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：把这张卡解放，从手卡·卡组把1张「秘异三变」卡除外才能发动。除外的卡种类的1只以下怪兽从手卡·卡组特殊召唤，自己失去那只怪兽的原本攻击力数值的基本分。 ●怪兽：「秘异三变猛兽」 ●魔法：「秘异三变秘法家」 ●陷阱：「秘异三变武装者」'),
(8200556, 'Myutant ST-46', '被检体 秘异三变体ST-46', '被検体ミュートリアST－４６', 'Effect Monster', 'Psychic', 'WATER', 3, 500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「秘异三变」魔法·陷阱卡加入手卡。 ②：把这张卡解放，把1张手卡或者自己场上的表侧表示的卡除外才能发动。除外的卡种类的1只以下怪兽从手卡·卡组特殊召唤。 ●怪兽：「秘异三变猛兽」 ●魔法：「秘异三变秘法家」 ●陷阱：「秘异三变武装者」'),
(79194594, 'Myutant Synthesis', '统合秘异三变联体', 'シンセシス・ミュートリアス', 'Fusion Monster', 'Psychic', 'WATER', 9, 2500, 2000, '属性不同的「秘异三变」怪兽×2 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡融合召唤成功的场合，以场上1张卡为对象才能发动。那张卡破坏。 ②：对方把效果发动时才能发动。这个回合，表侧表示的这张卡不受那个效果以及相同种类（怪兽·魔法·陷阱）的对方的效果影响。 ③：融合召唤的这张卡被对方破坏的场合才能发动。选除外的1张自己的「秘异三变」卡加入手卡。'),
(6182103, 'Myutant Ultimus', '究极体 秘异三变联体', '究極体ミュートリアス', 'Fusion Monster', 'Psychic', 'DARK', 10, 3500, 3000, '8星以上的「秘异三变」怪兽×3 这个卡名的①②的效果1回合各能使用1次。 ①：卡的效果发动时，把和那个效果相同种类（怪兽·魔法·陷阱）的1张「秘异三变」卡从自己的手卡·墓地以及自己场上的表侧表示的卡之中除外才能发动。那个发动无效并除外。 ②：融合召唤的这张卡被对方破坏的场合才能发动。选除外的自己的「秘异三变」卡3种类（怪兽·魔法·陷阱）各最多1张加入手卡。'),
(34876719, 'N.As.H. Knight', '沉魂救济帝车骑士', 'N・As・H Knight', 'XYZ Monster', 'Aqua', 'WATER', 5, 1700, 2700, '5星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：只要场上有「No.」怪兽存在，这张卡不会被战斗破坏。 ②：自己·对方的主要阶段，把这张卡2个超量素材取除才能发动。从额外卡组选1只「No.101」～「No.107」其中任意种的「No.」超量怪兽在这张卡下面重叠作为超量素材。那之后，可以选这张卡以外的场上1只表侧表示怪兽在这张卡下面重叠作为超量素材。'),
(1984618, 'Nadir Servant', '天底的使徒', '天底の使徒', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从额外卡组把1只怪兽送去墓地。那之后，把持有送去墓地的怪兽的攻击力以下的攻击力的1只「教导」怪兽或「阿不思的落胤」从自己的卡组·墓地加入手卡。这张卡的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。'),
(97518132, 'Naelshaddoll Ariel', '囚影依之巫女 艾莉娅儿', '影依の巫女 エリアル', 'Flip Effect Monster', 'Psychic', 'WATER', 4, 1000, 1800, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合，以自己的除外状态的1只「影依」怪兽为对象才能发动。那只怪兽表侧守备表示或里侧守备表示特殊召唤。 ②：这张卡被效果送去墓地的场合，以自己·对方的墓地的卡合计最多3张为对象才能发动。那些卡除外。'),
(63053267, 'Nagel''s Protection', '奈格尔守护天', 'ナーゲルの守護天', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己的主要怪兽区域的「廷达魔三角」怪兽不会被战斗以及对方的效果破坏。 ②：自己的「廷达魔三角」怪兽给与对方战斗伤害的场合，1回合只有1次让那次伤害变成2倍。 ③：把墓地的这张卡除外，从手卡丢弃1张「廷达魔三角」卡才能发动。从卡组把1张「奈格尔守护天」加入手卡。'),
(2881864, 'Naglfar, Generaider Boss of Fire', '炎之创王 纳古尔法', '炎の王 ナグルファー', 'Effect Monster', 'Beast-Warrior', 'FIRE', 9, 3100, 200, '这个卡名的②的效果1回合只能使用1次。 ①：「炎界王战 纳吉尔法王」在自己场上只能有1只表侧表示存在。 ②：自己场上的卡被战斗·效果破坏的场合，可以作为代替把自己场上1只「王战」怪兽或者兽战士族怪兽破坏。'),
(98931003, 'Nanana', '纳纳纳', 'ナナナ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只7星或者7阶怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时上升700。'),
(70948327, 'Nanobreaker', '纳米破坏者', 'ナノブレイカー', 'Effect Monster', 'Machine', 'EARTH', 4, 1600, 1800, '这张卡攻击3星以下的表侧表示怪兽的场合，不进行伤害计算把那只怪兽直接破坏。'),
(40172183, 'Narrow Pass', '狭窄的通路', '狭き通路', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '双方场上的怪兽都在2只以下时才能发动。双方都至多只能往自己场上召唤2只怪兽。'),
(18158397, 'Natural Disaster', '自然灾害', 'ナチュラル・ディザスター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次名字带有「云魔物」的怪兽的效果把对方控制的卡破坏送去墓地，给与对方基本分500分伤害。'),
(62896588, 'Natural Tune', '自然调整', 'ナチュラル・チューン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只4星以下的通常怪兽发动。选择怪兽只要在场上表侧表示存在当作调整使用。'),
(83467607, 'Nature''s Reflection', '自然反射', 'リフレクト・ネイチャー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个回合，对方发动的给与基本分伤害的效果变成给与对方基本分伤害的效果。'),
(99150062, 'Naturia Antjaw', '大植然蚂蚁颚', 'ナチュル・アントジョー', 'Effect Monster', 'Insect', 'EARTH', 2, 400, 200, '对方对怪兽的特殊召唤成功时，可以从自己卡组把1只3星以下的名字带有「自然」的怪兽特殊召唤。'),
(20174189, 'Naturia Bamboo Shoot', '大植然竹笋', 'ナチュル・バンブーシュート', 'Effect Monster', 'Plant', 'EARTH', 5, 2000, 2000, '把名字带有「自然」的怪兽解放作上级召唤成功的这张卡只要在场上表侧表示存在，对方不能把魔法·陷阱卡发动。'),
(2956282, 'Naturia Barkion', '大植然龙', 'ナチュル・パルキオン', 'Synchro Monster', 'Dragon', 'EARTH', 6, 2500, 1800, '地属性调整＋调整以外的地属性怪兽1只以上 ①：陷阱卡发动时，把自己墓地2张卡除外才能发动。这张卡在场上表侧表示存在的场合，那个发动无效并破坏。'),
(44789585, 'Naturia Beans', '自然豆一族', 'ナチュル・ビーンズ', 'Effect Monster', 'Plant', 'EARTH', 2, 100, 1200, '这张卡1回合只有1次不会被战斗破坏。场上表侧表示存在的这张卡被选择作为攻击对象时，给与对方基本分500分伤害。'),
(33198837, 'Naturia Beast', '大植然兽', 'ナチュル・ビースト', 'Synchro Monster', 'Beast', 'EARTH', 5, 2200, 1700, '地属性调整＋调整以外的地属性怪兽1只以上 ①：魔法卡发动时，从自己卡组上面把2张卡送去墓地才能发动。这张卡在场上表侧表示存在的场合，那个发动无效并破坏。'),
(27762803, 'Naturia Beetle', '自然甲虫', 'ナチュル・ビートル', 'Effect Monster', 'Insect', 'EARTH', 4, 400, 1800, '每次魔法卡发动，这张卡的原本攻击力·守备力交换。'),
(34813545, 'Naturia Blessing', '大植然春风', 'ナチュルの春風', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动。 ●从自己的手卡·墓地选1只「自然」怪兽特殊召唤。 ●用包含「自然」怪兽的自己场上的怪兽为素材作同调召唤。 ●从自己场上把融合怪兽卡决定的包含「自然」怪兽的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(42110434, 'Naturia Butterfly', '大植然蝴蝶', 'ナチュル・バタフライ', 'Tuner Monster', 'Insect', 'EARTH', 3, 500, 1200, '1回合1次，对方怪兽的攻击宣言时才能发动。把自己卡组最上面1张卡送去墓地，那次攻击无效。'),
(29942771, 'Naturia Camellia', '大植然山茶花', 'ナチュル・カメリア', 'Tuner Monster', 'Plant', 'EARTH', 4, 1400, 700, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「自然」卡送去墓地。 ②：只要这张卡在怪兽区域存在，自己为让「自然」怪兽的效果发动而把怪兽解放的场合，可以作为代替从自己卡组上面把2张卡送去墓地。 ③：对方对怪兽的召唤·特殊召唤成功的场合才能发动。从自己墓地选1只「自然」怪兽特殊召唤。'),
(60668166, 'Naturia Cherries', '大植然樱桃', 'ナチュル・チェリー', 'Tuner Monster', 'Plant', 'EARTH', 1, 200, 200, '这张卡被对方从场上送去墓地的场合，可以从自己卡组把最多2只「自然樱桃」里侧守备表示特殊召唤。'),
(33866130, 'Naturia Cliff', '自然壁', 'ナチュル・クリフ', 'Effect Monster', 'Rock', 'EARTH', 4, 1500, 1000, '这张卡从场上送去墓地时，可以从自己卡组把1只4星以下的名字带有「自然」的怪兽在自己场上表侧攻击表示特殊召唤。'),
(98437424, 'Naturia Cosmobeet', '自然甜菜菊', 'ナチュル・コスモスビート', 'Tuner Monster', 'Plant', 'EARTH', 2, 1000, 700, '对方对怪兽的通常召唤成功时，这张卡可以从手卡特殊召唤。'),
(70083723, 'Naturia Dragonfly', '自然蜻蜓', 'ナチュル・ドラゴンフライ', 'Effect Monster', 'Insect', 'EARTH', 4, 1200, 400, '这张卡不会被和攻击力2000以上的怪兽的战斗破坏。这张卡的攻击力上升自己墓地存在的名字带有「自然」的怪兽数量×200的数值。'),
(37349495, 'Naturia Eggplant', '自然茄子', 'ナチュル・エッグプラント', 'Effect Monster', 'Plant', 'EARTH', 2, 1000, 700, '这张卡从场上送去墓地时，可以选择自己墓地存在的「自然茄子」以外的1只名字带有「自然」的怪兽加入手卡。'),
(99916754, 'Naturia Exterio', '大植然龙兽', 'ナチュル・エクストリオ', 'Fusion Monster', 'Beast', 'EARTH', 10, 2800, 2400, '「自然兽」＋「自然木鳞龙」 这张卡的融合召唤不用上记的卡不能进行。 ①：魔法·陷阱卡发动时，从自己墓地把1张卡除外，把卡组最上面的卡送去墓地才能发动。这张卡在场上表侧表示存在的场合，那个发动无效并破坏。'),
(37322745, 'Naturia Forest', '大植然森林', 'ナチュルの森', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '把对方控制的卡的发动无效的场合，可以从自己卡组把1只3星以下的名字带有「自然」的怪兽加入手卡。'),
(11390349, 'Naturia Fruitfly', '自然飞蝇', 'ナチュル・フライトフライ', 'Effect Monster', 'Insect', 'EARTH', 3, 800, 1500, '只要这张卡在自己场上表侧表示存在，对方场上表侧表示存在的怪兽的攻击力·守备力下降自己场上表侧表示存在的名字带有「自然」的怪兽数量×300的数值。1回合1次，可以把对方场上表侧表示存在的1只守备力是0的怪兽的控制权直到结束阶段时得到。'),
(90555947, 'Naturia Gaiastrio', '大植然盖亚星狮', 'ナチュル・ガイアストライオ', 'Fusion Monster', 'Rock', 'EARTH', 10, 3200, 2100, '地属性同调怪兽×2 ①：只以场上的卡1张为对象的魔法·陷阱·怪兽的效果发动时，把1张手卡送去墓地才能发动。那个发动无效并破坏。'),
(80555116, 'Naturia Guardian', '自然守护者', 'ナチュル・ガーディアン', 'Effect Monster', 'Plant', 'EARTH', 4, 1600, 400, '对方对怪兽的召唤成功时，这张卡的攻击力直到结束阶段时上升300。'),
(84905691, 'Naturia Horneedle', '大植然蜂针', 'ナチュル・ホーストニードル', 'Effect Monster', 'Insect', 'EARTH', 4, 1800, 100, '对方对怪兽的特殊召唤成功时，把这张卡以外的自己场上表侧表示存在的1只名字带有「自然」的怪兽解放才能发动。那些怪兽破坏。这个效果在对方回合也能发动。'),
(47795344, 'Naturia Hydrangea', '大植然绣球花', 'ナチュル・ハイドランジー', 'Effect Monster', 'Plant', 'EARTH', 5, 1900, 2000, '自己场上的名字带有「自然」的怪兽的效果发动的回合，这张卡可以从手卡特殊召唤。'),
(19605133, 'Naturia Ladybug', '大植然瓢虫', 'ナチュル・レディバグ', 'Effect Monster', 'Insect', 'EARTH', 1, 100, 100, '自己对名字带有「自然」的同调怪兽的同调召唤成功时，自己墓地存在的这张卡可以在自己场上特殊召唤。此外，自己的主要阶段时把这张卡解放，选择自己场上表侧表示存在的1只名字带有「自然」的怪兽才能发动。选择的怪兽的攻击力直到这个回合的结束阶段时上升1000。'),
(43932460, 'Naturia Landoise', '大植然陆龟', 'ナチュル・ランドオルス', 'Synchro Monster', 'Rock', 'EARTH', 7, 2350, 1600, '地属性调整＋调整以外的地属性怪兽1只以上 只要这张卡在场上表侧表示存在，可以把手卡1张魔法卡送去墓地，效果怪兽的效果的发动无效并破坏。'),
(16527176, 'Naturia Leodrake', '大植然狮面草', 'ナチュル・ガオドレイク', 'Synchro Monster', 'Beast', 'EARTH', 9, 3000, 1800, '地属性调整＋调整以外的地属性怪兽1只以上'),
(51254980, 'Naturia Mantis', '大植然螳螂', 'ナチュル・マンティス', 'Effect Monster', 'Insect', 'EARTH', 4, 1700, 1500, '对方对怪兽的召唤成功时，可以从手卡把1只名字带有「自然」的怪兽送去墓地，那只怪兽破坏。'),
(24694698, 'Naturia Marron', '大植然栗子', 'ナチュル・マロン', 'Effect Monster', 'Plant', 'EARTH', 3, 1200, 700, '这张卡召唤成功时，可以从自己卡组把1只名字带有「自然」的怪兽送去墓地。此外，1回合1次，可以选择自己墓地存在的2只名字带有「自然」的怪兽回到卡组，从自己卡组抽1张卡。'),
(93454062, 'Naturia Mole Cricket', '大植然蝼蛄', 'ナチュル・モルクリケット', 'Effect Monster', 'Insect', 'EARTH', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把这张卡解放才能发动。从卡组把1只「自然」怪兽特殊召唤。攻击力最高的怪兽在对方场上存在的场合，这个效果特殊召唤的数量可以变成2只。 ②：这张卡在墓地存在的状态，对方从额外卡组把怪兽特殊召唤的场合或者自己从额外卡组把「自然」怪兽特殊召唤的场合才能发动。这张卡特殊召唤。'),
(17285476, 'Naturia Mosquito', '自然蚊', 'ナチュル・モスキート', 'Effect Monster', 'Insect', 'EARTH', 1, 200, 300, '只要自己场上有这张卡以外的名字带有「自然」的怪兽表侧表示存在，对方不能选择这张卡作为攻击对象。这张卡以外的自己场上表侧表示存在的名字带有「自然」的怪兽的战斗发生的对自己的战斗伤害由对方代受。'),
(7304544, 'Naturia Pineapple', '大植然菠萝', 'ナチュル・パイナポー', 'Effect Monster', 'Plant', 'EARTH', 2, 100, 100, '在自己场上表侧表示存在的怪兽作为植物族。自己的准备阶段这张卡在墓地存在，自己场上不存在魔法·陷阱卡的场合，这张卡可以在自己场上特殊召唤。这个效果在自己场上不存在表侧表示的「自然菠萝」，自己墓地只存在植物族·兽族怪兽的场合才能发动。'),
(96653775, 'Naturia Pumpkin', '自然南瓜', 'ナチュル・パンプキン', 'Effect Monster', 'Plant', 'EARTH', 4, 1400, 800, '对方场上有怪兽存在的场合这张卡召唤成功时，可以从手卡把1只名字带有「自然」的怪兽特殊召唤。'),
(87649699, 'Naturia Ragweed', '大植然豚草', 'ナチュル・ラグウィード', 'Effect Monster', 'Plant', 'EARTH', 3, 1200, 2000, '对方在抽卡阶段以外抽卡时，可以把自己场上表侧表示存在的这张卡送去墓地，从自己卡组抽2张卡。'),
(54161401, 'Naturia Rock', '自然岩', 'ナチュル・ロック', 'Effect Monster', 'Rock', 'EARTH', 3, 1200, 1200, '陷阱卡发动时，可以从自己卡组上面把1张卡送去墓地，从手卡把这张卡特殊召唤。'),
(61049315, 'Naturia Rosewhip', '大植然蔷薇鞭', 'ナチュル・ローズウィップ', 'Tuner Monster', 'Plant', 'EARTH', 3, 400, 1700, '只要这张卡在场上表侧表示存在，对方玩家1回合魔法·陷阱卡只能发动1次。'),
(3734202, 'Naturia Sacred Tree', '大植然神星树', 'ナチュルの神星樹', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把自己场上1只昆虫族·地属性怪兽解放才能发动。从卡组把1只4星以下的植物族·地属性怪兽特殊召唤。 ②：把自己场上1只植物族·地属性怪兽解放才能发动。从卡组把1只4星以下的昆虫族·地属性怪兽特殊召唤。 ③：这张卡被送去墓地的场合发动。从卡组把「自然的神星树」以外的1张「自然」卡加入手卡。'),
(25654671, 'Naturia Spiderfang', '自然蜘蛛牙', 'ナチュル・スパイダーファング', 'Effect Monster', 'Insect', 'EARTH', 4, 2100, 400, '这张卡若不在对方把魔法·陷阱·效果怪兽的效果发动的回合则不能攻击宣言。'),
(23051413, 'Naturia Stag Beetle', '自然锹甲', 'ナチュル・スタッグ', 'Effect Monster', 'Insect', 'EARTH', 6, 2200, 1500, '这张卡进行攻击的战斗步骤时以及伤害步骤时对方把魔法·陷阱·效果怪兽的效果发动时，选择自己墓地存在的1只名字带有「自然」的怪兽才能发动。选择的怪兽从墓地特殊召唤。这个效果1回合只能使用1次。'),
(25866285, 'Naturia Stinkbug', '大植然椿象', 'ナチュル・スティンクバグ', 'Tuner Monster', 'Insect', 'EARTH', 3, 200, 500, '自己场上表侧表示存在的名字带有「自然」的怪兽成为攻击对象时，把自己场上表侧表示存在的这张卡送去墓地才能发动。那次攻击无效，战斗阶段结束。'),
(55099248, 'Naturia Strawberry', '自然草莓', 'ナチュル・ストロベリー', 'Effect Monster', 'Plant', 'EARTH', 4, 1600, 1200, '对方对怪兽的召唤·特殊召唤成功时，直到这个回合的结束阶段时这张卡的攻击力上升召唤·特殊召唤的1只怪兽的等级×100的数值。这个效果1回合只能使用1次。'),
(7478431, 'Naturia Sunflower', '大植然向日葵', 'ナチュル・サンフラワー', 'Effect Monster', 'Plant', 'EARTH', 2, 500, NULL, '①：对方把怪兽的效果发动时，把这张卡和自己场上1只「自然」怪兽解放才能发动。那个发动无效并破坏。'),
(70261145, 'Naturia Tulip', '自然郁金香', 'ナチュル・トライアンフ', 'Tuner Monster', 'Plant', 'EARTH', 2, 600, 1500, '只要这张卡在自己场上表侧表示存在，每次对方把魔法·陷阱卡发动，自己场上表侧表示存在的名字带有「自然」的怪兽的攻击力直到那个回合的结束阶段时上升500。'),
(16940215, 'Naturia Vein', '大植然叶脉', 'ナチュル・ナーブ', 'Tuner Monster', 'Plant', 'EARTH', 1, 200, 300, '①：对方把魔法·陷阱卡发动时，把这张卡和自己场上1只「自然」怪兽解放才能发动。那个发动无效并破坏。'),
(24644634, 'Naturia White Oak', '自然白橡树', 'ナチュル・ホワイトオーク', 'Effect Monster', 'Plant', 'EARTH', 4, 1800, 1400, '这张卡成为对方的卡的效果的对象时才能发动。把自己场上表侧表示存在的这张卡送去墓地，从自己卡组把2只4星以下的名字带有「自然」的怪兽特殊召唤。这个效果特殊召唤的怪兽不能攻击宣言，自己的结束阶段时破坏。'),
(62405028, 'Nauya, the Ogdoadic Remnant', '溟界之滓－纳漪亚', '溟界の滓－ナイア', 'Effect Monster', 'Reptile', 'DARK', 4, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡送去墓地才能发动。从卡组把1只爬虫类族·光属性怪兽送去墓地。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「溟界」魔法·陷阱卡加入手卡。');